mapper.select:
        /*	설  명 : 성적활동평가비율조회	*/
        SELECT	*
        FROM 	TB_LMS_SBJCT	S
        		LEFT	JOIN	TB_LMS_MRK_ITM_STNG		MIS		ON	S.SBJCT_ID = MIS.SBJCT_ID
        		LEFT	JOIN	TB_LMS_CMMN_CD CC	ON 	CC.UP_CD   = 'MRK_ITM_TYCD' AND MIS.MRK_ITM_TYCD = CC.CD 
										        		AND CC.ORG_ID  = #{orgId}
										          		AND CC.LANG_CD = NVL(#{langCd}, 'ko')

												          AND MIS.MRK_ITM_USEYN = #{mrkItmUseyn}

        WHERE 	MIS.SBJCT_ID = #{sbjctId}
        ORDER 	BY	CC.CD_SEQNO
